<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; ?>
<div class="topbar"><h1>Projects</h1></div>
<?php if (!$rows): ?><div class="empty">No projects yet. They are created automatically when orders are paid.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Project</th><th>Customer</th><th>Service</th><th>Status</th><th>Progress</th><th>Updated</th></tr></thead><tbody>
<?php foreach ($rows as $p): ?><tr><td><a href="/admin/projects/<?= e($p['number']) ?>"><b><?= e($p['title']) ?></b></a><div class="small muted"><?= e($p['number']) ?></div></td><td class="small"><?= e($p['name'] ?: $p['email']) ?></td><td class="small"><?= e($p['service_slug']) ?></td><td><?php $badge($p['status']); ?></td><td style="min-width:120px"><div class="progress"><span style="width:<?= (int)$p['progress'] ?>%"></span></div><span class="small"><?= (int)$p['progress'] ?>%</span></td><td class="small"><?= e(substr($p['updated_at'], 0, 16)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
